import brainmass, brainstate, braintools, brainunit as u, jax, jax.numpy as jnp, numpy as np
from seizure_recruitment import DT,DURATION,FAST_TIME_CONSTANT,ULTRASLOW_TIME_CONSTANT,PERMITTIVITY_TIME_CONSTANT,MAX_DELAY,CONNECTIVITY,N_STEPS,STIMULUS_START_STEP,STIMULUS_STOP_STEP,classify_bursts

class M(brainstate.nn.Module):
 def __init__(self,x0,ks):
  super().__init__(); self.r=brainmass.EpileptorStep(3,x0=x0,Kvf=1.,Ks=ks,tt=1*u.ms/FAST_TIME_CONSTANT,r=FAST_TIME_CONSTANT/PERMITTIVITY_TIME_CONSTANT,tau=ULTRASLOW_TIME_CONSTANT/FAST_TIME_CONSTANT,init_x1=braintools.init.Constant(-1.5)); self.h=brainstate.nn.Delay(jnp.full(3,-1.5),time=MAX_DELAY,init=braintools.init.Constant(-1.5))
 def update(self,stim,k,d):
  self.h.update(self.r.x1.value); ds=jnp.rint(d/DT).astype(jnp.int32); delayed=self.h.retrieve_at_step(ds); src=jnp.broadcast_to(delayed,CONNECTIVITY.shape); c=brainmass.diffusive_coupling(src,self.r.x1.value,CONNECTIVITY,k); self.r(c+stim); return self.r.x1.value

def run(x0n,ks,k,d,p):
 with brainstate.environ.context(dt=DT):
  m=M(jnp.asarray([-2.4,x0n,x0n]),ks); brainstate.nn.init_all_states(m)
  def step(i):
   on=(i>=STIMULUS_START_STEP)&(i<STIMULUS_STOP_STEP); stim=jnp.asarray([on,False,False])*p
   with brainstate.environ.context(i=i,t=i*DT): return m(stim,k,d)
  return brainstate.transform.for_loop(step,jnp.arange(N_STEPS))

x0s=jnp.asarray([-2.3,-2.2,-2.1,-2.0,-1.9]); kss=jnp.asarray([0.,-0.5,-1.,-2.,0.5,1.]); ksweep=jnp.asarray([1.2,2.,4.]); ds=jnp.asarray([5.,20.,40.])*u.ms
xx,kk,cc,dd=jnp.meshgrid(x0s,kss,ksweep,ds.to_decimal(u.ms),indexing='ij')
flat=[a.reshape(-1) for a in (xx,kk,cc,dd)]
x=brainstate.transform.vmap(run)(flat[0],flat[1],flat[2],flat[3]*u.ms,jnp.full(flat[0].shape,3.))
x=jax.block_until_ready(x); rec,on,win,route=classify_bursts(x)
# no-stim matching susceptibility and Ks at k=4
xn=brainstate.transform.vmap(run)(x0s.repeat(len(kss)),jnp.tile(kss,len(x0s)),jnp.full((len(x0s)*len(kss),),4.),jnp.full((len(x0s)*len(kss),),5.)*u.ms,jnp.zeros((len(x0s)*len(kss),)))
xn=jax.block_until_ready(xn); rn,on_n,wn,route_n=classify_bursts(xn)
valid={}
for i,(a,b) in enumerate(zip(np.repeat(np.array(x0s),len(kss)),np.tile(np.array(kss),len(x0s)))): valid[(float(a),float(b))]=not np.asarray(rn[i]).any()
count=0
for i in range(x.shape[0]):
 if bool(route[i]) and valid[(float(flat[0][i]),float(flat[1][i]))]:
  print('ROUTED x0,ks,k,d',*[float(a[i]) for a in flat], 'on',np.asarray(on[i]),'win',np.asarray(win[i])); count+=1
print('valid routed total',count)
print('no stimulus failures:')
for i in range(rn.shape[0]):
 if np.asarray(rn[i]).any(): print(float(np.repeat(np.array(x0s),len(kss))[i]),float(np.tile(np.array(kss),len(x0s))[i]),np.asarray(rn[i]),np.asarray(on_n[i]),np.asarray(wn[i]))
PY"

